sql_reference:
SELECT dayname(TRY_CAST(order_purchase_timestamp AS TIMESTAMP)) AS jour_semaine,
       COUNT(*) AS commandes
FROM entrepot.orders GROUP BY 1 ORDER BY commandes DESC;

SELECT COUNT(*) AS messages_blancs
FROM entrepot.order_reviews
WHERE review_comment_message IS NOT NULL AND TRIM(review_comment_message) = '';

SELECT COUNT(*) AS lignes_totales,
       COUNT(DISTINCT geolocation_zip_code_prefix) AS codes_postaux_distincts
FROM entrepot.geolocation;

SELECT ROUND(AVG(LENGTH(review_comment_message)), 1) AS longueur_moyenne
FROM entrepot.order_reviews
WHERE review_comment_message IS NOT NULL AND TRIM(review_comment_message) <> '';

SELECT COUNT(*) AS commentaires_livraison
FROM entrepot.order_reviews
WHERE review_comment_message ILIKE '%entrega%' OR review_comment_message ILIKE '%atraso%';

SELECT CASE WHEN customer_state = 'SP' THEN 'Sao Paulo' ELSE 'autres etats' END AS zone,
       COUNT(*) AS clients
FROM entrepot.customers GROUP BY 1 ORDER BY clients DESC;

